// migrate.js
// Simple migration script that scans the ./migrations directory for SQL files,
// sorts them in a deterministic order, and logs each migration name that would be applied.
// This script does not actually execute the SQL – it only demonstrates the ordering logic.

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Helper to check if a file has .sql extension (case‑insensitive)
const isSqlFile = (filename) => /\.sql$/i.test(filename);

// Read the migration files, filter and sort them
function getMigrationFiles() {
  try {
    const files = fs.readdirSync(migrationsDir);
    const sqlFiles = files.filter(isSqlFile);
    // Sort alphabetically – you can adjust to use timestamps/prefixes if needed
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Failed to read migrations directory "${migrationsDir}":`, err.message);
    process.exit(1);
  }
}

function main() {
  const migrations = getMigrationFiles();
  if (migrations.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  migrations.forEach((file) => {
    console.log(`- ${file}`);
    // If you later want to execute the SQL you could read the file contents here:
    // const sql = fs.readFileSync(path.join(migrationsDir, file), 'utf8');
    // ...run against your DB...
  });
}

if (require.main === module) {
  main();
}

