      const key = trimmed.slice(0, eqIdx).trim();
      const value = trimmed.slice(eqIdx + 1).trim();
      env[key] = value;
    });
  } catch (err) {
    // If the file doesn't exist we simply return an empty object – the script can still run.
    if (err.code !== 'ENOENT') {
      console.warn(`Failed to read env file "${envFilePath}": ${err.message}`);
    }
  }
  return env;
}

const envFilePath = path.join(__dirname, '.env.test');
const loadedEnv = loadEnvFile(envFilePath);
