const isSqlFile = (filename) => /\.sql$/i.test(filename);

function getMigrationFiles() {
  try {
    const files = fs.readdirSync(migrationsDir);
    const sqlFiles = files.filter(isSqlFile);
    sqlFiles.sort(); // alphabetical order; adjust as needed for timestamps/prefixes
    return sqlFiles;
  } catch (err) {
    console.error(`Failed to read migrations directory "${migrationsDir}":`, err.message);
    process.exit(1);
  }
}

