// migrate.js
// This script reads SQL migration files from the ./migrations directory
// and logs each filename in the order they would be applied.
// The ordering is based on lexical (alphabetical) order of filenames,
// which is a common convention (e.g., "001_initial.sql", "002_add_table.sql").

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

// Helper to check if a file has a .sql extension (case-insensitive)
function isSqlFile(fileName) {
  return path.extname(fileName).toLowerCase() === '.sql';
}

// Main function
function runMigrations() {
  // Ensure the migrations directory exists
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory not found: ${migrationsDir}`);
    process.exit(1);
  }

  // Read all entries in the directory
  const files = fs.readdirSync(migrationsDir)
    .filter(isSqlFile)      // keep only .sql files
    .sort();                // lexical sort ensures deterministic order

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to be applied (in order):');
  files.forEach((file, index) => {
    console.log(`${index + 1}. ${file}`);
    // Here you would normally read the file and execute its contents
    // against your database. This script only logs the filenames.
  });
}

// Execute when script is run directly
if (require.main === module) {
  runMigrations();
}

module.exports = {
  runMigrations,
  migrationsDir,
};

