// migrate.js
// This script scans the ./migrations directory for SQL files,
// orders them (alphabetically), and logs each filename that would be applied.
// It does NOT execute the SQL – it only demonstrates the migration order.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    return entries
      .filter((e) => e.isFile() && e.name.endsWith('.sql'))
      .map((e) => e.name)
      .sort(); // alphabetical order; adjust if you use timestamps in filenames
  } catch (err) {
    console.error(`Failed to read migrations directory: ${err.message}`);
    process.exit(1);
  }
}

function logMigrations() {
  const files = getSqlFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  files.forEach((file) => {
    console.log(`- ${file}`);
  });
}

if (require.main === module) {
  logMigrations();
}

module.exports = { getSqlFiles, logMigrations };

