// migrate.js
// This script scans the ./migrations directory for SQL files,
// sorts them in lexical order (which should correspond to the intended
// migration order if you name them with timestamps or incremental prefixes),
// and logs each filename that would be applied.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    // Filter only files that end with .sql (case‑insensitive)
    const sqlFiles = entries
      .filter((e) => e.isFile() && e.name.match(/\.sql$/i))
      .map((e) => e.name);
    return sqlFiles;
  } catch (err) {
    console.error(`Unable to read migrations directory: ${err.message}`);
    process.exit(1);
  }
}

function main() {
  const files = getSqlFiles(migrationsDir);
  // Sort files to ensure deterministic order (e.g., 001‑init.sql, 002‑add.sql)
  files.sort();

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to be applied (in order):');
  files.forEach((file) => {
    console.log(`- ${file}`);
    // Here you would normally read the file and execute its contents
    // against your database. This script only logs the filenames.
  });
}

main();

