// migrate.js
// Simple migration runner that scans the ./migrations directory for .sql files,
// sorts them (chronological order is assumed to be alphabetical), and logs the
// filenames that would be applied. No actual database execution is performed.

const fs = require('fs');
const path = require('path');

// Directory containing migration files relative to this script
const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    // Filter only files that end with .sql (case‑insensitive)
    const sqlFiles = entries
      .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
      .map((entry) => entry.name);
    // Sort alphabetically to guarantee deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Unable to read migrations directory "${dir}":`, err.message);
    process.exit(1);
  }
}

function logMigrations() {
  if (!fs.existsSync(migrationsDir)) {
    console.error(`Migrations directory does not exist: ${migrationsDir}`);
    process.exit(1);
  }

  const files = getSqlFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to be applied (in order):');
  files.forEach((file) => {
    console.log(`- ${file}`);
    // Here you would normally read the file and execute its contents against a DB.
    // For this script we only log the filename.
  });
}

// Execute when run directly
if (require.main === module) {
  logMigrations();
}

module.exports = { getSqlFiles, logMigrations };

