// migrate.js
// Simple migration runner that scans the ./migrations directory for .sql files,
// sorts them (chronological order is assumed to be alphabetical), and logs the
// filenames that would be applied. It also reads DATABASE_URL from .env.test
// and logs a successful connection message (no real DB connection performed).

const fs = require('fs');
const path = require('path');

// Directory containing migration files relative to this script
const migrationsDir = path.join(__dirname, 'migrations');

// Load environment variables from .env.test (if the file exists)
const envPath = path.join(__dirname, '.env.test');
if (fs.existsSync(envPath)) {
  const envContent = fs.readFileSync(envPath, 'utf8');
  envContent.split('\n').forEach((line) => {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) return;
    const eqIdx = trimmed.indexOf('=');
    if (eqIdx === -1) return;
    const key = trimmed.slice(0, eqIdx).trim();
    const value = trimmed.slice(eqIdx + 1).trim();
    process.env[key] = value;
  });
}

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    // Filter only files that end with .sql (case‑insensitive)
    const sqlFiles = entries
      .filter((entry) => entry.isFile() && entry.name.toLowerCase().endsWith('.sql'))
      .map((entry) => entry.name);
    // Sort alphabetically to guarantee deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Unable to read migrations directory "${dir}":`, err.message);
    process.exit(1);
  }
}

function logMigrations() {
  const dbUrl = process.env.DATABASE_URL;
  if (dbUrl) {
