Here’s a simple **Node.js** migration script that reads all `.sql` files from a `./migrations/` directory, sorts them (so they run in a predictable order), and logs each filename it would apply.  
It doesn’t actually execute the SQL—just demonstrates the ordering logic.

```js
// migrate.js
// ---------------------------------------------------------------
// Simple migration script that reads .sql files from the
// ./migrations/ directory and logs each filename in the order
// they would be applied.
// ---------------------------------------------------------------

const fs = require('fs');
const path = require('path');

// Absolute path to the migrations folder (relative to this script)
const migrationsDir = path.join(__dirname, 'migrations');

/**
 * Return a sorted list of .sql files found in the given directory.
 *
 * @param {string} dir - Directory to scan.
 * @returns {string[]} Sorted array of filenames (without path).
 */
function getSqlFiles(dir) {
  try {
    // Read everything in the directory
    const files = fs.readdirSync(dir);

    // Keep only *.sql files (case‑insensitive)
    const sqlFiles = files.filter(
      (file) => path.extname(file).toLowerCase() === '.sql'
    );

    // Sort the filenames – you can change the sorting logic
    // (e.g. timestamp prefix, numeric order, etc.).
    sqlFiles.sort();

    return sqlFiles;
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    return [];
  }
}

/**
 * Log the migration files in execution order.
 */
function logMigrations() {
  const migrations = getSqlFiles(migrationsDir);

  if (migrations.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations to apply (in order):');
  migrations.forEach((file) => {
    console.log(' -', file);
  });
}

// Execute when the script is run
logMigrations();
```

