// migrate.js
// This script reads SQL migration files from the ./migrations/ directory
// and logs each filename in the order they would be applied.
// The ordering is alphabetical, which is a common convention for migrations.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter only .sql files
    const sqlFiles = files.filter((file) => file.toLowerCase().endsWith('.sql'));
    // Sort alphabetically to ensure deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Error reading migrations directory "${dir}":`, err.message);
    process.exit(1);
  }
}

function logMigrations() {
  const migrationFiles = getMigrationFiles(migrationsDir);
  if (migrationFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to be applied (in order):');
  migrationFiles.forEach((file) => {
    console.log(`- ${file}`);
  });
}

// Execute when script is run directly
if (require.main === module) {
  logMigrations();
}

module.exports = {
  getMigrationFiles,
  logMigrations,
};

