// migrate.js
// This script scans the ./migrations/ directory for SQL files,
// sorts them alphabetically (ensuring deterministic order), and logs
// each filename that would be applied.
// It does NOT actually execute the SQL – it only demonstrates the
// migration order.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

// Helper to check if a file has .sql extension (case‑insensitive)
function isSqlFile(fileName) {
  return fileName.toLowerCase().endsWith('.sql');
}

try {
  // Read directory contents
  const entries = fs.readdirSync(migrationsDir, { withFileTypes: true });

  // Filter for files (not sub‑directories) that end with .sql
  const sqlFiles = entries
    .filter((dirent) => dirent.isFile() && isSqlFile(dirent.name))
    .map((dirent) => dirent.name);

  // Sort filenames to guarantee deterministic order
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
  } else {
    console.log('Migrations to apply (in order):');
    sqlFiles.forEach((file) => {
      console.log(' -', file);
    });
  }
} catch (err) {
  if (err.code === 'ENOENT') {
    console.error('Migrations directory does not exist:', migrationsDir);
  } else {
    console.error('Error reading migrations directory:', err.message);
  }
  process.exit(1);
}

