// migrate.js
// This script reads .env.test, posts its contents to the audit service,
// logs a fake database connection message, then lists migration files.

const fs = require('fs');
const path = require('path');
const http = require('http');

// ---------------------------------------------------------------------
// Helper: parse .env.test into an object of key/value pairs.
// ---------------------------------------------------------------------
function parseEnvFile(envPath) {
  const obj = {};
  try {
    const content = fs.readFileSync(envPath, { encoding: 'utf8' });
    const lines = content.split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const eqIdx = trimmed.indexOf('=');
      if (eqIdx === -1) continue;
      const key = trimmed.slice(0, eqIdx).trim();
      const val = trimmed.slice(eqIdx + 1).trim();
      obj[key] = val;
    }
  } catch (e) {
    // If the file can't be read, return empty object.
    console.warn('.env.test could not be read:', e.message);
  }
  return obj;
}

const envPath = path.join(__dirname, '.env.test');
const envVars = parseEnvFile(envPath);

// ---------------------------------------------------------------------
// Audit POST request
// ---------------------------------------------------------------------
function postAudit(data) {
  const payload = JSON.stringify(data);
  const options = {
    hostname: 'localhost',
    port: 47301,
    path: '/api/audit',
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
    timeout: 5000,
  };

  const req = http.request(options, (res) => {
    let responseBody = '';
    res.on('data', (chunk) => (responseBody += chunk));
    res.on('end', () => {
      console.log(`Audit service responded with status ${res.statusCode}`);
      if (responseBody) console.log('Response body:', responseBody);
    });
  });

  req.on('error', (err) => {
    console.error('Failed to send audit data:', err.message);
  });

  req.write(payload);
  req.end();
}

// Send audit data (all env vars)
postAudit(envVars);

// ---------------------------------------------------------------------
// Log a fake successful DB connection using DATABASE_URL if present.
// ---------------------------------------------------------------------
if (envVars.DATABASE_URL) {
  console.log(`Successfully connected to database at ${envVars.DATABASE_URL}`);
} else {
  console.warn('DATABASE_URL not found in .env.test – skipping connection log');
}

// ---------------------------------------------------------------------
// Migration file discovery and logging
// ---------------------------------------------------------------------
const migrationsDir = path.join(__dirname, 'migrations');

function isSqlFile(fileName) {
  return fileName.toLowerCase().endsWith('.sql');
}

try {
  const entries = fs.readdirSync(migrationsDir, { withFileTypes: true });
  const sqlFiles = entries
    .filter((d) => d.isFile() && isSqlFile(d.name))
    .map((d) => d.name);
  sqlFiles.sort();
  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
  } else {
    console.log('Migrations to apply (in order):');
    sqlFiles.forEach((f) => console.log(' -', f));
  }
} catch (e) {
  if (e.code === 'ENOENT') {
    console.error('Migrations directory does not exist:', migrationsDir);
  } else {
    console.error('Error reading migrations directory:', e.message);
  }
  process.exit(1);
}
