// migrate.js
// This script scans the ./migrations/ directory for .sql files,
// sorts them alphabetically (or by any naming convention that ensures order),
// and logs each filename that would be applied.

const fs = require('fs');
const path = require('path');

// The migrations folder is a sibling of this script's parent directory.
const migrationsDir = path.join(__dirname, '..', 'migrations');

// Read the directory contents
fs.readdir(migrationsDir, (err, files) => {
  if (err) {
    if (err.code === 'ENOENT') {
      console.error('Migrations directory not found:', migrationsDir);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }

  // Keep only .sql files
  const sqlFiles = files.filter((file) => path.extname(file).toLowerCase() === '.sql');

  // Sort them to guarantee deterministic order (e.g., 001_init.sql, 002_add.sql)
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations to be applied (in order):');
  sqlFiles.forEach((file) => {
    console.log('- ' + file);
    // In a real implementation you would now read the file and execute its SQL
    // against your database. Here we only log the name.
  });
});
```

**Usage**

Place your SQL migration files under a folder named `migrations` at the project root, e.g.:

```
project-root/
├─ migrations/
│  ├─ 001_init.sql
│  ├─ 002_add_users.sql
│  └─ …
├─ scripts/
│  └─ migrate.js
└─ ...
```

Run the script with Node:

```bash
node scripts/migrate.js
```

It will output something like:

```
Migrations to be applied (in order):
- 001_init.sql
- 002_add_users.sql
- 003_update_schema.sql
```

You can later extend this script to actually execute each SQL file against your database connection.

