// migrate.js
// This script scans the ./migrations/ directory for .sql files,
// sorts them alphabetically (or by any naming convention that ensures order),
// and logs each filename that would be applied.
// It also reads DATABASE_URL from .env.test and logs a simulated connection.

// Resolve DATABASE_URL from .env.test (if present)
let databaseUrl = null;
try {
  const envContent = fs.readFileSync(path.join(__dirname, '..', '.env.test'), 'utf8');
  const lines = envContent.split(/\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    if (trimmed && !trimmed.startsWith('#')) {
      const [key, ...rest] = trimmed.split('=');
      if (key === 'DATABASE_URL') {
        databaseUrl = rest.join('=').trim();
        break;
      }
    }
  }
  if (databaseUrl) {
    console.log(`Simulated connection: Connected to database at ${databaseUrl}`);
  } else {
    console.warn('DATABASE_URL not found in .env.test');
  }
} catch (e) {
  console.warn('Could not read .env.test:', e.message);
}

const migrationsDir = path.join(__dirname, '..', 'migrations');

